const body = $json.body ?? $json;
const text = String(body.goal ?? body.task ?? body.message ?? '').trim();
if (!text) {
  return [{ json: { ok: false, status: 'BLOCKED', blocked: ['missing goal'], humanApprovalRequired: false, next: 'Provide goal/task/message.' } }];
}

const lower = text.toLowerCase();
const protectedRules = [
  ['code/files mutation', /\b(?:edit|modify|rewrite|change|write|patch|fix)\b.{0,40}\b(?:code|file|repo|repository|source)\b|\b(?:code|file|repo|repository|source)\b.{0,40}\b(?:edit|modify|rewrite|change|write|patch|fix)\b/i],
  ['merge/publish', /\bmerge\b|\bpublish\b|\brelease\b/i],
  ['deployment/production', /\bdeploy(?:ment)?\b|\bproduction\b/i],
  ['credentials/secrets', /\bpassword\b|\bpasscode\b|\botp\b|\bapi[ _-]?key\b|\baccess[ _-]?token\b|\bsecret\b|\bcredential\b/i],
  ['payment/purchase', /\bpayment\b|\bpurchase\b|\bbuy\b|\bpay\b|\brefund\b/i],
  ['destructive action', /\bdelete\b|\bdestroy\b|\bwipe\b|\bformat\b|\btruncate\b|\bdrop table\b/i],
  ['database migration', /\bdatabase migration\b|\bdb migration\b|\bmigrate production\b/i],
  ['external message', /\bsend\b.{0,20}\b(?:email|message|whatsapp|sms|notification)\b/i],
];
const blocked = protectedRules.filter(([, pattern]) => pattern.test(text)).map(([label]) => label);

let agent = 'Master Orchestrator Agent';
if (/n8n|workflow|webhook|automation|502/.test(lower)) agent = 'n8n Workflow Agent';
else if (/code|github|commit|pull request|pr|typescript|python|react/.test(lower)) agent = 'Coding and GitHub Agent';
else if (/bug|error|test|qa|regression|fail/.test(lower)) agent = 'Bug Fix and QA Agent';
else if (/security|permission|secret|credential|token|vulnerability/.test(lower)) agent = 'Security Agent';
else if (/docker|deploy|server|ops|health|runtime|ci|build/.test(lower)) agent = 'Deploy and Ops Agent';

const humanApprovalRequired = blocked.length > 0;
return [{
  json: {
    ok: true,
    goal: text,
    source: String(body.source ?? 'unknown').slice(0, 80),
    assignedAgent: agent,
    status: humanApprovalRequired ? 'BLOCKED' : 'READY',
    done: humanApprovalRequired ? [] : ['Goal accepted by HARSF Safe Router'],
    doing: [],
    blocked,
    humanApprovalRequired,
    next: humanApprovalRequired
      ? 'Ask the Human CEO for explicit approval before any protected action. Do not pass secrets in the goal.'
      : 'Pass this planning/read-only task to the selected agent or approved AI-model node.'
  }
}];
